const $=id=>document.getElementById(id),word=(key,params={})=>(copy[getLanguage()==='en'?'en':'zh'][key]||key).replace(/\{(\w+)\}/g,(_,name)=>String(params[name]??''));
const create=(tag,className,text)=>{const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node;};
const numeric=value=>Number.isFinite(value)?new Intl.NumberFormat(getLanguage()==='en'?'en-US':'zh-CN',{maximumFractionDigits:4}).format(value):'—';
const priceNumeric=value=>Number.isFinite(value)?new Intl.NumberFormat(getLanguage()==='en'?'en-US':'zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}).format(value):'—';
const rawNumeric=value=>Number.isFinite(value)?String(value):'—';
const compact=value=>new Intl.NumberFormat(getLanguage()==='en'?'en-US':'zh-CN',{notation:'compact',maximumFractionDigits:2}).format(value);
function stamp(value){if(!value||!Number.isFinite(Date.parse(value)))return word('unknown');return new Intl.DateTimeFormat(getLanguage()==='en'?'en-US':'zh-CN',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(value))+' ET';}
// Read per render so charts follow the day/night mode (see chart-palette.js).
const colors=new Proxy({},{get:(_,key)=>structurePalette()[key]});
let symbols=[],listBusy=false,listFailed=false,canRefresh=true,canManage=false,controller,historyController,viewMode='live',captureStarting=false,captureWatch=null,captureNote=null,historyPollTimer=null,historyPollBusy=false,historyObservedRunning=false,historyPermissionContext=null;
const getState=()=>controller.state;
function setOptions(select,options,value){select.replaceChildren(...options.map(([v,label])=>{const option=create('option',null,label);option.value=v;return option;}));select.value=options.some(option=>option[0]===value)?value:options[0]?.[0]||'';}
function metadata(snapshot){return `${word('checked')}: ${stamp(snapshot?.checkedAt)} · ${word('updated')}: ${stamp(snapshot?.providerUpdatedAt)}`;}
function available(snapshot){return snapshot&&Array.isArray(snapshot.profile)&&snapshot.profile.some(row=>Number.isFinite(row?.spot)&&Number.isFinite(row?.gex));}
function status(slot,kind){
  if(slot.busy)return word(slot.payload?'busy':'reading');
  if(slot.error){const message={NO_PERMISSION:'permission',AUTH_FAILED:'permission',AUTH_REQUIRED:'permission',NOT_CONFIGURED:'notConfigured',UNSUPPORTED_PROVIDER:'unsupported'}[slot.error];return word(message|| (slot.error==='RATE_LIMITED'?'partial':'failed'))+(slot.retained?' '+word('retained'):'');}
  if(!slot.payload||slot.payload.status==='unavailable')return word('notLoaded');
  if(slot.payload.stale||slot.payload.base?.stale||slot.payload.withoutNearest?.stale)return word('snapshotStale');
  if(slot.payload.status==='failed')return word('failed');
  return word(slot.payload.status==='partial'?'partial':'current');
}
function renderStatus(id,slot,kind){const node=$(id);node.textContent=status(slot,kind);node.classList.toggle('error',!!slot.error||slot.payload?.status==='failed');}
function refreshButton(id,slot,label){const remaining=Math.max(0,Math.ceil((slot.retryAt-Date.now())/1000));$(id).disabled=!getState().symbol||slot.busy||remaining>0||!canRefresh;$(id).textContent=slot.busy?word('busy'):remaining?word('cooldown',{n:remaining}):word(label);$(id).title=!canRefresh?word('noRefresh'):'';}
function legend(host,items){host.replaceChildren(...items.map(item=>{const part=create('span','structure-legend-item'),swatch=create('span','structure-swatch'+(item.point?' is-point':item.bar?' is-bar':''));swatch.style.setProperty('--series-color',item.color);part.append(swatch,document.createTextNode(item.label));return part;}));}
function snapshotCard(snapshot,key,expiries,record){
  const card=create('article','structure-snapshot'+(viewMode==='history'&&key==='withoutNearest'?' is-history-comparison':''));card.dataset.snapshot=key;card.append(create('h3',null,viewMode==='history'?archiveLabel(record,key==='base'?'primary':'comparison'):word(key==='base'?'base':'without')));
  const list=Array.isArray(snapshot?.selectedExpiries)?snapshot.selectedExpiries:expiries||[];
  card.append(create('p','structure-meta',`${word('expiries')}: ${list.length?list.join(' · '):'—'}`));
  if(key==='withoutNearest'&&viewMode==='live')card.append(create('p','structure-meta',`${word('excluded')}: ${snapshot?.excludedExpiry||getState().gamma.payload?.nearestExpiry||'—'}`));
  const levels=create('dl','structure-levels');
  for(const [label,value]of [['callWall',priceNumeric(snapshot?.callWall)],['putWall',priceNumeric(snapshot?.putWall)],['zeroGamma',Array.isArray(snapshot?.zeroGammaPoints)&&snapshot.zeroGammaPoints.length?snapshot.zeroGammaPoints.map(priceNumeric).join(' / '):word(snapshot?.zeroGammaDisclosed===true?'zerosNone':'unknown')]]){const cell=create('div');cell.append(create('dt',null,word(label)),create('dd',null,value));levels.append(cell);}card.append(levels);
  card.append(create('p','structure-meta',`${word('spot')}: ${priceNumeric(snapshot?.underlyingPrice)} · ${viewMode==='history'?archiveMetadata(record):metadata(snapshot)}`));
  if(snapshot?.stale||viewMode==='live'&&getState().gamma.retained)card.append(create('p','structure-warning',word('retained')));
  const reason={NO_REMAINING_EXPIRIES:'noRemaining',PROVIDER_FILTER_LIMIT:'filterLimit'}[snapshot?.reason];
  if(reason)card.append(create('p','structure-warning',word(reason)));else if(!snapshot||snapshot.status==='unavailable'||snapshot.status==='failed')card.append(create('p','structure-warning',word('missing')));
  return card;
}

