function historyReadStatus(kind){const state=historyController.state;if(state.busy||state.primary.busy||state.comparison.busy)return word('reading');if(state.error||state.primary.error||state.comparison.error)return word('historyFailed');if(state.primary.reset||state.comparison.reset)return word('historyReset');if(!state.primary[kind]&&!state.comparison[kind])return word('historyMissing');return word('historyLoaded');}
