  for(const id of ['structure-live-gamma-controls','structure-live-pain-controls'])$(id).hidden=history;
  $('structure-view-live').setAttribute('aria-pressed',String(!history));$('structure-view-history').setAttribute('aria-pressed',String(history));
  $('structure-history-reload').disabled=state.busy||!state.symbol;
  $('structure-view-tabs').setAttribute('aria-label',word('snapshotMode'));
  $('structure-history-capture').hidden=!canManage;$('structure-history-capture').disabled=captureStarting||!!captureWatch||state.daily?.running===true;$('structure-history-capture').textContent=word(captureStarting?'historyCaptureBusy':'historyCapture');$('structure-capture-status').textContent=captureNote?word(captureNote):'';
