  setOptions($('history-date-primary'),[['',word('historyNoDate')],...dates.map(row=>[row.date,row.date+' · '+row.recordCount+' '+word('historyRecords')])],state.primary.date);
  setOptions($('history-date-comparison'),[['',word('noComparison')],...dates.map(row=>[row.date,row.date+' · '+row.recordCount+' '+word('historyRecords')])],state.comparison.date);
  for(const side of ['primary','comparison']){const slot=state[side];setOptions($('history-gamma-'+side),[['',word('selectArchive')],...slot.headers.filter(record=>record.kind==='gamma').map(record=>[record.id,archiveOption(record)])],slot.gammaId);setOptions($('history-pain-'+side),[['',word('selectArchive')],...slot.headers.filter(record=>record.kind==='max_pain').map(record=>[record.id,archiveOption(record)])],slot.painId);$('history-gamma-'+side).disabled=slot.busy||!slot.date;$('history-pain-'+side).disabled=slot.busy||!slot.date;}
  $('structure-history-status').textContent=(state.busy?word('reading'):state.error?word('historyFailed'):!dates.length?word('historyEmpty'):word('historyLoaded'))+(state.index?.truncated||state.primary.truncated||state.comparison.truncated?' '+word('historyTruncated'):'');
